-- Phong Than "Lenh Bai Van Tien Tran" (magicscript 61470, task 2670; 2026-10-04, agent vtcc). Permanent, never consumed
-- (KItemList::ExecuteScript only calls main; this script never removes the item). Generated by
-- scratchpad\vtcc\gen.py - edit the generator, not this file. Doc: docs\features\lenh-bai-van-tien-thuong-chu-phong-than-20261004.md
-- Right click: pick one of the 4 tran (as Thien Hung). A closed tran is opened at once through PTVT_Open
-- (InitMission spawns tien / mobs / Dai phu, 30 s preparation then the normal 30-minute fight, timers, chests,
-- rewards, back to Tay Ky at the end); an open tran is joined (PTVT_Join = NewWorld + AddMSPlayer). Same code
-- path as PTVT_EnterRequest (vt_lib.lua) minus the level / unlock checks. Mission and GlobalValue 400..419 are
-- engine objects shared by every Lua state, so the servertimer tick (PTVT_Tick) sees the tran opened here.
-- No VNG limits: no schedule, no level, no ticket. Rewards are the VNG ones of a normal entry (drops of the tien,
-- Thong Thien and chests, vt_drop.lua; Thien Hung daily quest), never multiplied; the 1-hour cooldown is the limit.
-- Cooldown: task 2670 = server clock (seconds since 2000-01-01) of the last successful entry, 3600 s.
-- Lua 4 / engine: no top-level dofile (the library is loaded at call time, cwd = Server), menus <= 7 rows.

PTVK_ITEM = 61470
PTVK_TASK = 2670
PTVK_CD = 3600
PTVK_PREP = 30

function PTVK_Load()
	if not PTVT_Join then dofile("script\\phongthan\\vantien\\vt_lib.lua") end
end

-- map id of the player if the token may be used here (field maps, cities), else nil: never from inside
-- Van Tien tran (1079-1082), the battlefield (1071), events, instances or Thien Lao (1060)
function PTVK_SrcOk()
	local m = GetWorldPos()
	if not m then return nil end
	if m >= 1001 and m <= 1057 then return m end
	if m == 1065 or (m >= 1074 and m <= 1078) then return m end
	return nil
end

-- seconds since 2000-01-01 on the server clock (date()); fits a task value until 2068
function PTVK_Now()
	local y = tonumber(date("%Y")) or 2000
	local j = tonumber(date("%j")) or 1
	local h = tonumber(date("%H")) or 0
	local mi = tonumber(date("%M")) or 0
	local s = tonumber(date("%S")) or 0
	local d = (y - 2000) * 365 + floor((y - 1997) / 4) + j - 1
	return d * 86400 + h * 3600 + mi * 60 + s
end

-- seconds left of the 1-hour cooldown (0 = ready). A clock set back makes the token ready again.
function PTVK_Left()
	local last = GetTask(PTVK_TASK)
	if last <= 0 then return 0 end
	local left = last + PTVK_CD - PTVK_Now()
	if left <= 0 or left > PTVK_CD then return 0 end
	return left
end

function PTVK_LeftText(left)
	return floor(left / 60) .. " ph\243t " .. mod(left, 60) .. " gi\169y"
end

function PTVK_Say(title, o)
	local n = getn(o)
	local t = { title, n }
	local k = 1
	while k <= n do t[k + 2] = o[k] k = k + 1 end
	call(Say, t)
end

-- close row of every menu (the name the engine dialogs and the simulators expect)
function no()
end

function PTVK_Blocked()
	Say("<color=yellow>L\214nh B\181i V\185n Ti\170n Tr\203n<color>: kh\171ng d\239ng \174\173\238c \235 b\182n \174\229 n\181y (trong V\185n Ti\170n tr\203n, chi\213n tr\173\234ng, s\249 ki\214n, ph\227 b\182n, Thi\170n Lao). H\183y ra b\182n \174\229 ngo\181i ho\198c v\210 th\181nh tr\173\237c.", 1, "\167\227ng/no")
end

function PTVK_Main()
	PTVK_Load()
	local left = PTVK_Left()
	if left > 0 then
		Say("<color=yellow>L\214nh B\181i V\185n Ti\170n Tr\203n<color>: l\214nh b\181i \174ang h\229i, c\223n <color=red>" .. PTVK_LeftText(left) .. "<color> n\247a m\237i d\239ng l\185i \174\173\238c (m\231i l\199n d\239ng h\229i 60 ph\243t).", 1, "\167\227ng/no")
		return
	end
	local o = {}
	local n = 1
	while n <= 4 do
		o[n] = "Tr\203n " .. PTVT_NAME[n] .. " [" .. PTVT_StateText(n) .. "], n\170n c\202p " .. PTVT_MINLV[n] .. "+/PTVK_G" .. n
		n = n + 1
	end
	o[5] = "\167\227ng/no"
	PTVK_Say("<color=yellow>L\214nh B\181i V\185n Ti\170n Tr\203n<color>: ch\228n tr\203n \174\211 v\181o ngay. Tr\203n \174ang \174\227ng s\207 \174\173\238c m\235 ngay (chu\200n b\222 30 gi\169y) r\229i \174\184nh nh\173 th\203t. Kh\171ng c\199n \174\238i gi\234 m\235, kh\171ng c\199n c\202p v\181o, kh\171ng gi\237i h\185n s\232 l\199n trong ng\181y (ph\199n th\173\235ng nh\173 m\233t l\173\238t VNG b\215nh th\173\234ng). M\231i l\199n d\239ng h\229i 60 ph\243t.", o)
end

-- PTVT_EnterRequest without the level / unlock checks: 1 = the player is inside tran n
function PTVK_Enter(n)
	if not PTVT_D[n] then return 0 end
	if not PTVT_UseWorld(n) then
		Msg2Player("B\182n \174\229 V\185n Ti\170n tr\203n (" .. PTVT_NAME[n] .. ") ch\173a \174\173\238c n\185p tr\170n m\184y ch\241.")
		return 0
	end
	local pi = PlayerIndex
	if IsMission(n) == 1 and PTVT_GV(n, 0) == 3 then
		-- already cleared: start a fresh session when nobody is left inside (as Thien Hung)
		local inside = PTVT_Inside(n)
		PlayerIndex = pi
		if getn(inside) == 0 then PTVT_Close(n) end
	end
	PTVT_UseWorld(n)
	if IsMission(n) ~= 1 then
		local r = PTVT_Open(n, PTVK_PREP)
		PlayerIndex = pi
		if r ~= 1 then
			Msg2Player("Kh\171ng m\235 \174\173\238c V\185n Ti\170n tr\203n (" .. PTVT_NAME[n] .. ").")
			return 0
		end
		AddGlobalNews((GetName() or "") .. " d\239ng <color=yellow>L\214nh B\181i V\185n Ti\170n Tr\203n<color> m\235 V\185n Ti\170n tr\203n (" .. PTVT_NAME[n] .. ").")
	end
	PlayerIndex = pi
	local j = PTVT_Join(n)
	PlayerIndex = pi
	return j
end

function PTVK_Go(n)
	PTVK_Load()
	if not PTVT_D[n] then return end
	if PTVK_Left() > 0 then PTVK_Main() return end
	if not PTVK_SrcOk() then PTVK_Blocked() return end
	CloseDialog()
	local pi = PlayerIndex
	if PTVK_Enter(n) ~= 1 then return end
	PlayerIndex = pi
	SetTask(PTVK_TASK, PTVK_Now())
	if GetLevel() < PTVT_MINLV[n] then
		Msg2Player("Ch\243 \253: tr\203n n\181y d\181nh cho c\202p " .. PTVT_MINLV[n] .. " tr\235 l\170n, ti\170n v\181 Th\171ng Thi\170n Gi\184o Ch\241 r\202t m\185nh.")
	end
	Msg2Player("L\214nh B\181i V\185n Ti\170n Tr\203n: l\199n d\239ng ti\213p theo sau 60 ph\243t.")
end

function PTVK_G1() PTVK_Go(1) end
function PTVK_G2() PTVK_Go(2) end
function PTVK_G3() PTVK_Go(3) end
function PTVK_G4() PTVK_Go(4) end

function main(nItemIdx)
	PTVK_Main()
	return 0
end
